function accountHeaders(id?: string): Record<string, string> {
  if (!id) return {};
  if (id.length > 200 || !/^acct_[A-Za-z0-9]+$/.test(id)) throw new AdapterError("payments", "stripe", "invalid_request", "That seller payment account is invalid.");
